use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use regex::Regex;
use serde::{Deserialize, Serialize};
use sqlx::{PgPool, Row};
use std::time::Duration;

#[derive(Deserialize)]
struct SearchQuery {
    pattern: String,
    tenant_id: String,
}

#[derive(Serialize)]
struct SearchResult {
    id: i64,
    content: String,
    matched: bool,
}

/// Validates that the search pattern conforms to allowed syntax
/// Uses a regex to check the user-supplied pattern before compilation
fn validate_pattern(pattern: &str) -> bool {
    // Allow alphanumeric, basic wildcards, character classes
    let validator = Regex::new(r"^[a-zA-Z0-9.*+?\[\]\(\)\|\\{}^$, _-]+$").unwrap();
    validator.is_match(pattern) && pattern.len() <= 512
}

async fn search_documents(
    pool: web::Data<PgPool>,
    query: web::Query<SearchQuery>,
    req: HttpRequest,
) -> HttpResponse {
    let tenant_id = &query.tenant_id;
    let pattern = &query.pattern;

    // Validate pattern characters
    if !validate_pattern(pattern) {
        return HttpResponse::BadRequest().json(serde_json::json!({
            "error": "Invalid search pattern"
        }));
    }

    // Compile the user-supplied regex pattern
    // NOTE: The regex crate in Rust does NOT backtrack and is immune to
    // catastrophic backtracking in the traditional sense, BUT the compilation
    // itself can be expensive for complex patterns, and matching against
    // large haystacks with complex patterns can still cause high CPU usage
    let compiled_regex = match Regex::new(pattern) {
        Ok(r) => r,
        Err(_) => {
            return HttpResponse::BadRequest().json(serde_json::json!({
                "error": "Failed to compile pattern"
            }));
        }
    };

    // Set session variable for RLS - tenant isolation
    let set_tenant = format!("SET app.current_tenant = '{}'", tenant_id);
    if let Err(e) = sqlx::query(&set_tenant).execute(pool.get_ref()).await {
        return HttpResponse::InternalServerError().json(serde_json::json!({
            "error": "Database session error"
        }));
    }

    // Query documents - RLS policy ensures tenant isolation
    let rows = match sqlx::query("SELECT id, content FROM documents")
        .fetch_all(pool.get_ref())
        .await
    {
        Ok(r) => r,
        Err(_) => {
            return HttpResponse::InternalServerError().json(serde_json::json!({
                "error": "Query failed"
            }));
        }
    };

    // Apply regex matching on results
    let results: Vec<SearchResult> = rows
        .iter()
        .map(|row| {
            let id: i64 = row.get("id");
            let content: String = row.get("content");
            let matched = compiled_regex.is_match(&content);
            SearchResult { id, content, matched }
        })
        .collect();

    HttpResponse::Ok().json(results)
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "healthy"}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let database_url = std::env::var("DATABASE_URL")
        .unwrap_or_else(|_| "postgres://app:password@localhost/mydb".to_string());

    let pool = PgPool::connect(&database_url)
        .await
        .expect("Failed to connect to database");

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(pool.clone()))
            .route("/search", web::get().to(search_documents))
            .route("/health", web::get().to(health_check))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
